/// <summary>The native layout of <c>GstMessage</c>.</summary>
/// <remarks>
/// <para>
/// The mirror is only ever read through a pointer into memory that GStreamer
/// owns; it is never allocated, assigned or copied.
/// </para>
/// <para>
/// It stops at the first field that has no portable C# spelling. Every field
/// behind that one is private to the C implementation and is never read.
/// </para>
/// </remarks>
[StructLayout(LayoutKind.Sequential)]
internal unsafe struct MessageRaw
{
    /// <summary>The <c>mini_object</c> field.</summary>
    internal Gst.MiniObjectRaw MiniObject;

    /// <summary>The <c>type</c> field.</summary>
    internal Gst.MessageType Type;

    /// <summary>The <c>timestamp</c> field.</summary>
    internal ulong Timestamp;

    /// <summary>The <c>src</c> field.</summary>
    internal nint Src;

    /// <summary>The <c>seqnum</c> field.</summary>
    internal uint Seqnum;
}
